import { createComponentDispatch } from "./component-host/dispatch.js";
import type {
	LixStorageConfig,
	LixBinding,
	LixStorageProviderModule,
	SyncServerBindingOptions,
	TelemetryDispatch,
	TelemetryParentContext,
	OpenProgressDispatch,
	SnapshotRestoreBinding,
} from "./binding-types.js";
import { initializeWasm } from "./wasm-init.js";
import { restoreSnapshot } from "./snapshot-restore.js";

// Generated before TypeScript compilation and emitted beside this module.
// @ts-ignore Generated by build:wasm and absent in source-only checks.
import {
	createHosted,
	deleteHosted,
	openJsStorage,
	openJsStorageFromSnapshot,
	openMemory,
	openMemoryFromSnapshot,
	// @ts-ignore Generated by build:wasm and absent in source-only checks.
} from "./wasm/lix_js_sdk.js";

export async function openLixBinding(
	storage: LixStorageConfig,
	telemetry?: TelemetryDispatch,
	telemetryParent?: TelemetryParentContext,
	server?: SyncServerBindingOptions,
	openProgress?: OpenProgressDispatch,
	snapshot?: ReadableStream<Uint8Array>,
): Promise<LixBinding> {
	// Load the plugin runtime alongside WASM and finish before the repository
	// can be used offline. Start after the worker has initialized its module
	// loader: Vite's dynamic-import wrapper is unavailable at module evaluation.
	const componentCompiler = import("./component-host/index.js");
	await initializeWasm();
	const { compileComponent, initializeComponentCompiler } = await componentCompiler;
	await initializeComponentCompiler();
	const componentDispatch = createComponentDispatch(compileComponent);
	switch (storage.kind) {
		case "memory":
			return (
				snapshot
					? restoreSnapshot(
							snapshot,
							openMemoryFromSnapshot(
								telemetry,
								telemetryParent,
								openProgress,
								componentDispatch,
								storage.durability,
							) as SnapshotRestoreBinding<LixBinding>,
						)
					: openMemory(
						telemetry,
						telemetryParent,
						server,
						openProgress,
						componentDispatch,
						storage.durability,
					)
			) as Promise<LixBinding>;
		case "jsStorage": {
			const module = (await import(
				/* @vite-ignore */ storage.moduleUrl
			)) as unknown as LixStorageProviderModule;
			if (typeof module.createLixStorageProvider !== "function") {
				throw new TypeError(
					`Storage provider module '${storage.moduleUrl}' does not export createLixStorageProvider()`,
				);
			}
			const provider = await module.createLixStorageProvider(storage.options);
			try {
				const binding = (await (snapshot
					? restoreSnapshot(
							snapshot,
							openJsStorageFromSnapshot(
								provider,
								telemetry,
								telemetryParent,
								openProgress,
								componentDispatch,
								storage.durability,
							) as SnapshotRestoreBinding<LixBinding>,
						)
					: openJsStorage(
							provider,
							telemetry,
							telemetryParent,
							server,
							openProgress,
							componentDispatch,
							storage.durability,
						))) as unknown as LixBinding;
				return binding;
			} catch (error) {
				await provider.close().catch(() => undefined);
				throw error;
			}
		}
		case "filesystem":
			throw new Error("FilesystemStorage is only available in Node.js");
	}
}

export async function createHostedBinding(
	server: import("./binding-types.js").HostedServerBindingOptions,
): Promise<import("./types.js").HostedLix> {
	await initializeWasm();
	return createHosted(server);
}
export async function deleteHostedBinding(
	server: import("./binding-types.js").HostedServerBindingOptions,
): Promise<void> {
	await initializeWasm();
	await deleteHosted(server);
}

export async function convertReplicaBinding(storage:LixStorageConfig,server:SyncServerBindingOptions,branchId?:string):Promise<void> {
 const migration = await import("./migration-binding.browser.js");
 return migration.convertReplicaBinding(storage, server, branchId);
}
export async function retryReplicaMigrationCleanupBinding(storage:LixStorageConfig,server:SyncServerBindingOptions):Promise<number> {
 const migration = await import("./migration-binding.browser.js");
 return migration.retryReplicaMigrationCleanupBinding(storage, server);
}
